    ("Superior temporal gyrus (Lateral part)", "Üst temporal girus", "Gyrus temporalis superior", "Arka kısmı Wernicke alanını (Brodmann 22) içerir; baskın tarafta hasarı akıcı (duyusal) afazi yapar."),
    ("Middle temporal gyrus", "Orta temporal girus", "Gyrus temporalis medius", "Temporal lobun dış yüzünün orta girusu."),
    ("Inferior temporal gyrus", "Alt temporal girus", "Gyrus temporalis inferior", "Temporal lobun alt kenarındaki girus; nesne tanımaya katılır."),
    ("Superior temporal sulcus", "Üst temporal sulkus", "Sulcus temporalis superior", "Üst ve orta temporal girusları ayıran sulkus."),
    ("Inferior temporal sulcus", "Alt temporal sulkus", "Sulcus temporalis inferior", "Orta ve alt temporal girusları ayıran sulkus."),
    ("Transverse temporal gyri", "Transvers temporal girusler (Heschl)", "Gyri temporales transversi", "Üst temporal girusun lateral yarık içindeki yüzeyinde primer işitme korteksi (Brodmann 41, 42)."),
    ("Temporal plane", "Planum temporale", "Planum temporale", "Heschl girusunun arkasındaki düzlük; baskın yarıkürede daha büyüktür ve dil işlemeye katılır."),
    ("Temporal pole", "Temporal kutup", "Polus temporalis", "Temporal lobun ön ucu."),
    ("Lateral occipitotemporal gyrus", "Lateral oksipitotemporal girus (fusiform)", "Gyrus occipitotemporalis lateralis", "Temporal lobun alt yüzündeki girus; yüz tanıma alanını içerir (hasarında prozopagnozi)."),
    ("Medial occipitotemporal gyrus (Parahippocampal*)", "Parahipokampal girus", "Gyrus parahippocampalis", "Hipokampusun yanındaki girus; ön ucu unkus olarak kıvrılır, tentoryal herniasyonda bu kısım fıtıklaşır."),
    ("Occipitotemporal sulcus (Lateral part*)", "Oksipitotemporal sulkus", "Sulcus occipitotemporalis", "Alt temporal ve fusiform girusları ayıran sulkus."),
    # --- Meninges, CSF ------------------------------------------------------------------
    ("Spinal dura", "Spinal dura mater", "Dura mater spinalis", "Omuriliği saran sert zar; S2 hizasında sonlanır, epidural aralıkla omur kanalından ayrılır (epidural anestezi)."),
    ("Falx cerebri", "Falx cerebri", "Falx cerebri", "İki yarıküre arasına inen orak biçimli dura katlantısı; üst ve alt sagittal sinüsleri taşır."),
    ("Tentorium cerebelli", "Tentorium cerebelli", "Tentorium cerebelli", "Serebellumu oksipital loblardan ayıran dura çadırı; çentiğinden beyin sapı geçer, unkal herniasyon bu kenardan olur."),
    ("Choroid plexus", "Koroid pleksus", "Plexus choroideus", "Ventriküllerde beyin omurilik sıvısını (günde ~500 mL) üreten damarsal yapı."),
    # --- Spinal cord --------------------------------------------------------------------
    ("Central canal", "Santral kanal", "Canalis centralis", "Omuriliğin ortasındaki dar kanal; IV. ventrikülle devam eder, genişlemesi siringomiyelidir."),
    ("Central canal'", "Santral kanal (alt kısım)", "Canalis centralis", "Omurilik santral kanalının alt bölümü."),
    ("Anterior horn of spinal cord", "Omuriliğin ön boynuzu", "Cornu anterius medullae spinalis", "Alt motor nöronları içeren gri cevher; poliomiyelit ve ALS'de hasar görür."),
    ("Posterior horn of spinal cord", "Omuriliğin arka boynuzu", "Cornu posterius medullae spinalis", "Duyu liflerinin sinaps yaptığı gri cevher; substantia gelatinosa ağrı modülasyonunda rol alır."),
    ("Nucleus of accessory nerve", "Aksesuar sinir çekirdeği", "Nucleus nervi accessorii", "C1–C5 ön boynuzundaki, sternokleidomastoid ve trapezi uyaran çekirdek."),
    ("Intermediolateral nucleus", "İntermediolateral çekirdek", "Nucleus intermediolateralis", "T1–L2 lateral boynuzundaki sempatik preganglionik nöronlar."),
    ("Intermediomedial nucleus", "İntermediomedial çekirdek", "Nucleus intermediomedialis", "Ara bölgedeki visseral duyu çekirdeği."),
    ("Lateral intermediate substance", "Lateral ara madde", "Substantia intermedia lateralis", "Omurilik ara bölgesinin lateral kısmı."),
    ("Nucleus proprius", "Nükleus proprius", "Nucleus proprius", "Arka boynuzun ana duyusal çekirdeği."),
    ("Spinal reticular process", "Spinal retiküler çıkıntı", "Formatio reticularis spinalis", "Arka boynuz yanında gri ve beyaz cevherin karıştığı ağ."),
    ("Posterolateral tract", "Lissauer traktusu", "Tractus posterolateralis", "Ağrı ve ısı liflerinin arka boynuza girmeden önce bir-iki segment yukarı-aşağı seyrettiği yol."),
    ("White matter of spinal cord", "Omuriliğin beyaz cevheri", "Substantia alba medullae spinalis", "Çıkan ve inen yolları içeren ön, yan ve arka kordonlar."),
    ("Gracile fasciculus", "Fasciculus gracilis (Goll)", "Fasciculus gracilis", "Alt gövde ve bacaklardan ince dokunma, vibrasyon ve pozisyon duyusu taşıyan medial arka kordon."),
    ("Cuneate fasciculus", "Fasciculus cuneatus (Burdach)", "Fasciculus cuneatus", "T6 üstünden, üst gövde ve kollardan aynı duyuları taşıyan lateral arka kordon."),
    ("Lateral corticospinal tract", "Lateral kortikospinal yol", "Tractus corticospinalis lateralis", "Medullada çaprazlaşmış istemli motor liflerin ana yolu; hasarında aynı tarafta üst motor nöron bulguları (Babinski) görülür."),
    ("Anterior corticospinal tract", "Ön kortikospinal yol", "Tractus corticospinalis anterior", "Çaprazlaşmamış kortikospinal lifler; segment düzeyinde çaprazlaşarak gövde kaslarına gider."),
    ("Lateral spinothalamic tract", "Lateral spinotalamik yol", "Tractus spinothalamicus lateralis", "Karşı taraftan ağrı ve ısı duyusu taşır; Brown-Séquard sendromunda karşı tarafta ağrı-ısı kaybı olur."),
    ("Anterior spinothalamic tract", "Ön spinotalamik yol", "Tractus spinothalamicus anterior", "Kaba dokunma ve basınç duyusunu taşır."),
    ("Spinotectal tract", "Spinotektal yol", "Tractus spinotectalis", "Duyusal bilgiyi üst kollikulusa taşıyarak baş-göz yönelimini sağlar."),
    ("Anterior spinocerebellar tract", "Ön spinoserebellar yol", "Tractus spinocerebellaris anterior", "Alt ekstremiteden bilinçsiz propriosepsiyonu üst serebellar pedünkülle serebelluma taşır."),
    ("Posterior spinocerebellar tract", "Arka spinoserebellar yol", "Tractus spinocerebellaris posterior", "Clarke çekirdeğinden başlayıp alt serebellar pedünkülle aynı taraf serebelluma ulaşır."),
    ("Rubrospinal tract", "Rubrospinal yol", "Tractus rubrospinalis", "Kırmızı çekirdekten başlayıp fleksör kas tonusunu artıran inen yol."),
    ("Tectospinal tract", "Tektospinal yol", "Tractus tectospinalis", "Üst kollikulustan boyun kaslarına; başı görsel uyaranlara çeviren refleks yolu."),
    ("Lateral vestibulospinal tract", "Lateral vestibülospinal yol", "Tractus vestibulospinalis lateralis", "Lateral vestibüler çekirdekten antigravite ekstansör kaslarını uyaran yol."),
    ("Medial vestibulospinal tract", "Medial vestibülospinal yol", "Tractus vestibulospinalis medialis", "Baş-boyun postürünü dengeleyen inen yol."),
    ("Medial reticulospinal tract", "Medial retikülospinal yol", "Tractus reticulospinalis medialis", "Pons retiküler formasyonundan ekstansör tonusu artıran yol."),
    ("Lateral reticulospinal tract", "Lateral retikülospinal yol", "Tractus reticulospinalis lateralis", "Medulla retiküler formasyonundan ekstansör tonusu azaltan yol."),
    ("Anterior fasciculus proprius", "Ön fasciculus proprius", "Fasciculus proprius anterior", "Omurilik segmentleri arası bağlantıları sağlayan kısa lifler (ön kordon)."),
    ("Lateral fasciculus proprius", "Lateral fasciculus proprius", "Fasciculus proprius lateralis", "Segmentler arası kısa lifler (yan kordon)."),
    ("Posterior fasciculus proprius", "Arka fasciculus proprius", "Fasciculus proprius posterior", "Segmentler arası kısa lifler (arka kordon)."),
    # --- Autonomic ----------------------------------------------------------------------
    ("Sympathetic trunk", "Sempatik gövde", "Truncus sympathicus", "Omurganın iki yanında kafa tabanından koksikse uzanan ganglion zinciri; boyun ganglionlarının hasarı Horner sendromu yapar."),
    ("Ganglia of sympathetic trunk", "Sempatik gövde ganglionları", "Ganglia trunci sympathici", "Sempatik postganglionik nöronların gövdelerini içeren paravertebral ganglionlar; stellat ganglion C7–T1 hizasındadır."),
    ("Sympathetic nerves", "Sempatik sinirler", "Nervi sympathici", "Sempatik gövdeden iç organlara ve damarlara giden dallar; splanknik sinirleri de içerir."),
    # --- Cranial nerves -----------------------------------------------------------------
    ("Olfactory nerve (I)", "Koku siniri (I)", "Nervus olfactorius (I)", "Koku epitelinden lamina cribrosa deliklerinden geçerek bulbus olfactorius'a ulaşan lifler; ön kafa tabanı kırığında anozmi gelişir."),
    ("Optic nerve (II)", "Görme siniri (II)", "Nervus opticus (II)", "Retina ganglion hücre aksonları; optik kanaldan geçer, beyin zarlarıyla sarılı olduğundan kafa içi basınç artışında papil ödem görülür."),
    ("Oculomotor nerve (III)", "Okülomotor sinir (III)", "Nervus oculomotorius (III)", "Dört göz kası, levator palpebrae ve parasempatik pupilla liflerini taşır. Felcinde göz aşağı-dışa kayar, pitoz ve midriyazis olur; arka komünikan anevrizması sık nedendir."),
    ("Trochlear nerve (IV)", "Troklear sinir (IV)", "Nervus trochlearis (IV)", "Üst eğik kası uyaran, beyin sapının arkasından çıkan tek ve en ince kraniyal sinir; en uzun intrakraniyal seyre sahiptir."),
    ("Trigeminal nerve (V)", "Trigeminal sinir (V)", "Nervus trigeminus (V)", "En büyük kraniyal sinir; yüzün duyusunu (V1, V2, V3) ve çiğneme kaslarını (V3) taşır. Trigeminal nevralji en sık V2–V3 alanında olur."),
    ("Abducens nerve (VI)", "Abdusens sinir (VI)", "Nervus abducens (VI)", "Lateral düz kası uyarır; uzun seyri nedeniyle kafa içi basınç artışında en sık etkilenen sinirdir."),
    ("Facial nerve (VII)", "Fasiyal sinir (VII)", "Nervus facialis (VII)", "Mimik kaslarını, ön 2/3 dil tadını, gözyaşı ve tükürük bezlerini ve m. stapedius'u uyarır. Foramen stylomastoideum'dan çıkar; periferik felcinde yüzün tüm yarısı tutulur (Bell paralizisi)."),
    ("Vestibulocochlear nerve (VIII)", "Vestibülokoklear sinir (VIII)", "Nervus vestibulocochlearis (VIII)", "İşitme ve denge duyularını taşır; serebellopontin açıdaki vestibüler schwannom (akustik nörinom) tek taraflı işitme kaybı yapar."),
    ("Glossopharyngeal nerve (IX)", "Glossofaringeal sinir (IX)", "Nervus glossopharyngeus (IX)", "Arka 1/3 dil tat ve duyusu, farinks duyusu, karotis sinüs ve cisimciği, parotis parasempatiği ile m. stylopharyngeus'u uyarır; öğürme refleksinin afferent koludur."),
    ("Vagus nerve (X)", "Vagus siniri (X)", "Nervus vagus (X)", "Boyun, göğüs ve karın organlarına parasempatik lifler, farinks ve larinks kaslarına motor lifler taşıyan en geniş dağılımlı kraniyal sinir; öğürme refleksinin efferent koludur."),
    ("Accessory nerve (XI)", "Aksesuar sinir (XI)", "Nervus accessorius (XI)", "Sternokleidomastoid ve trapez kaslarını uyarır; arka üçgende yüzeyel olduğundan cerrahide yaralanabilir (omuz düşüklüğü)."),
    ("Hypoglossal nerve (XII)", "Hipoglossal sinir (XII)", "Nervus hypoglossus (XII)", "Dil kaslarını uyarır; periferik felcinde dil dışarı çıkarılınca felçli tarafa sapar."),
    ("Chorda tympani", "Chorda tympani", "Chorda tympani", "Fasiyal sinirin orta kulaktan geçen dalı; n. lingualis'e katılarak dilin ön 2/3 tadını ve submandibular-sublingual bezlerin parasempatiğini taşır."),
    ("Ophthalmic nerve", "Oftalmik sinir (V1)", "Nervus ophthalmicus (V1)", "Trigeminalin duyusal ilk dalı; alın, burun sırtı ve korneayı innerve eder, kornea refleksinin afferentidir. Zona oftalmikus'ta burun ucu tutulumu (Hutchinson) göz tutulumunu düşündürür."),
    ("Maxillary nerve", "Maksiller sinir (V2)", "Nervus maxillaris (V2)", "Foramen rotundum'dan çıkan duyusal dal; orta yüz, üst dişler, damak ve maksiller sinüsü innerve eder."),
    ("Meningeal branch of maxillary nerve", "Maksiller sinirin meningeal dalı", "Ramus meningeus nervi maxillaris", "Orta kafa çukuru durasının duyusunu taşıyan küçük dal."),
    ("Sensory root of trigeminal nerve", "Trigeminalin duyusal kökü", "Radix sensoria nervi trigemini", "Trigeminal ganglionun ponsa giden büyük kökü."),
    ("Motor root of trigeminal nerve", "Trigeminalin motor kökü", "Radix motoria nervi trigemini", "Ganglionun altından geçip mandibular sinire katılan, çiğneme kaslarını uyaran kök."),
    ("Anterior division of mandibular nerve", "Mandibular sinirin ön bölümü", "Divisio anterior nervi mandibularis", "Çoğunlukla motor bölüm; çiğneme kaslarına ve n. buccalis'e dal verir."),
    ("Posterior division of mandibular nerve", "Mandibular sinirin arka bölümü", "Divisio posterior nervi mandibularis", "Çoğunlukla duyusal bölüm; n. auriculotemporalis, n. lingualis ve n. alveolaris inferior'u verir."),
    ("Buccal nerve", "Bukkal sinir", "Nervus buccalis", "Yanak derisi ve mukozasının duyusunu taşır (bukkinatörü uyaran fasiyal sinirin dalıyla karıştırılmamalıdır)."),
    ("Inferior alveolar nerve", "Alt alveoler sinir", "Nervus alveolaris inferior", "Mandibular kanalda seyreden, alt dişleri innerve eden dal; diş hekimliğinde blok anestezisi yapılır."),
    ("Lingual nerve", "Lingual sinir", "Nervus lingualis", "Dilin ön 2/3 genel duyusunu taşır; chorda tympani ile tat ve parasempatik lifleri alır. Alt yirmi yaş dişi çekiminde yaralanabilir."),
    ("Mental nerve", "Mental sinir", "Nervus mentalis", "Foramen mentale'den çıkan, alt dudak ve çene derisini innerve eden dal."),
    ("Nerve to mylohyoid muscle", "Milohiyoid sinir", "Nervus mylohyoideus", "Milohiyoid kas ve digastrik ön karnı uyaran dal."),
    ("Cochlear nerve", "Koklear sinir", "Nervus cochlearis", "Kokleadan işitme bilgisini taşıyan kısım."),
    ("Vestibular nerve", "Vestibüler sinir", "Nervus vestibularis", "Yarım daire kanalları, utrikül ve sakkülden denge bilgisini taşıyan kısım; iltihabı vestibüler nörittir."),
    # --- Spinal nerves ------------------------------------------------------------------
    ("Spinal ganglion", "Spinal (arka kök) ganglion", "Ganglion sensorium nervi spinalis", "Arka kök üzerindeki, duyusal nöron gövdelerini içeren ganglion; zona virüsü burada latent kalır."),
    ("Anterior root of spinal nerve", "Spinal sinirin ön kökü", "Radix anterior nervi spinalis", "Motor ve (T1–L2, S2–S4'te) otonom lifleri taşıyan kök."),
    ("Posterior root of spinal nerve", "Spinal sinirin arka kökü", "Radix posterior nervi spinalis", "Duyusal lifleri taşıyan kök."),
    ("Cauda equina", "Kauda ekuina", "Cauda equina", "Konus medullaris'ten aşağı inen lomber ve sakral sinir kökleri; basısı idrar-dışkı kaçırma ve eyer anestezisi ile acil cerrahi gerektirir."),
    ("Intercostal nerves", "İnterkostal sinirler", "Nervi intercostales", "T1–T11 spinal sinirlerinin ön dalları; kaburga altındaki olukta ven-arter-sinir (VAN) sırasıyla seyreder, interkostal bloğu kaburganın alt kenarından yapılır."),
    # Brachial plexus
    ("Roots of brachial plexus", "Brakiyal pleksus kökleri", "Radices plexus brachialis", "C5–T1 ön dalları; skalen kaslar arasından çıkar."),
    ("Superior trunk of brachial plexus", "Üst trunkus", "Truncus superior plexus brachialis", "C5–C6 köklerinin birleşmesiyle oluşur; doğum travmasında gerilmesi Erb-Duchenne felci ('garson eli') yapar."),
    ("Middle trunk of brachial plexus", "Orta trunkus", "Truncus medius plexus brachialis", "C7 kökünün devamı."),
    ("Inferior trunk of brachial plexus", "Alt trunkus", "Truncus inferior plexus brachialis", "C8–T1 köklerinden oluşur; hasarı Klumpke felci (pençe el), servikal kaburga ve Pancoast tümörü basısı yapar."),
    ("Anterior division of superior trunk of brachial plexus", "Üst trunkusun ön bölümü", "Divisio anterior trunci superioris", "Lateral kordona katılan ön bölüm."),
    ("Posterior division of superior trunk of brachial plexus", "Üst trunkusun arka bölümü", "Divisio posterior trunci superioris", "Arka kordona katılan bölüm."),
    ("Anterior division of middle trunk of brachial plexus", "Orta trunkusun ön bölümü", "Divisio anterior trunci medii", "Lateral kordona katılan bölüm."),
    ("Posterior division of middle trunk of brachial plexus", "Orta trunkusun arka bölümü", "Divisio posterior trunci medii", "Arka kordona katılan bölüm."),
    ("Anterior division of inferior trunk of brachial plexus", "Alt trunkusun ön bölümü", "Divisio anterior trunci inferioris", "Medial kordu oluşturan bölüm."),
    ("Posterior division of inferior trunk of brachial plexus", "Alt trunkusun arka bölümü", "Divisio posterior trunci inferioris", "Arka kordona katılan bölüm."),
    ("Posterior cord of brachial plexus", "Arka kord", "Fasciculus posterior plexus brachialis", "Üç trunkusun arka bölümlerinden oluşur; n. axillaris ve n. radialis başta olmak üzere ekstansörleri uyaran sinirleri verir."),
    ("Dorsal scapular nerve", "Dorsal skapular sinir", "Nervus dorsalis scapulae", "C5'ten çıkıp rhomboid kaslar ve levator scapulae'yı uyarır."),
    ("Long thoracic nerve", "Uzun torasik sinir (Bell)", "Nervus thoracicus longus", "C5–C7 köklerinden çıkıp göğüs yan duvarında seyreder ve serratus anterior'u uyarır; mastektomide yaralanırsa kanatlı skapula gelişir."),
    ("Subclavian nerve", "Subklavian sinir", "Nervus subclavius", "Üst trunkustan çıkıp m. subclavius'u uyarır."),
    ("Suprascapular nerve", "Suprascapular sinir", "Nervus suprascapularis", "Üst trunkustan çıkar, incisura scapulae'dan geçerek supra- ve infraspinatus'u uyarır."),
    ("Lateral pectoral nerve", "Lateral pektoral sinir", "Nervus pectoralis lateralis", "Lateral korddan çıkıp büyük göğüs kasını uyarır."),
    ("Medial pectoral nerve", "Medial pektoral sinir", "Nervus pectoralis medialis", "Medial korddan çıkıp küçük ve büyük göğüs kaslarını uyarır."),
    ("Musculocutaneous nerve", "Muskulokutanöz sinir", "Nervus musculocutaneus", "Lateral korddan çıkar, korakobrakialisi deler; kolun ön bölme kaslarını uyarır ve önkol lateral derisinin duyusunu verir."),
    ("Lateral antebrachial cutaneous nerve", "Lateral önkol deri siniri", "Nervus cutaneus antebrachii lateralis", "Muskulokutanöz sinirin duyusal uç dalı; önkolun lateral derisini innerve eder."),
    ("Median nerve", "Median sinir (n. medianus)", "Nervus medianus", "Lateral ve medial kordların birleşmesiyle oluşur; önkol fleksörlerinin çoğunu, tenar kasları ve lateral 3,5 parmağın avuç içi duyusunu sağlar. Karpal tünelde sıkışması en sık tuzak nöropatidir ('maymun eli', 'kutsama eli')."),
    ("Muscular branches of median nerve", "Median sinirin kas dalları", "Rami musculares nervi mediani", "Önkol ön bölmesindeki kaslara giden dallar."),
    ("Anterior interosseous nerve of forearm", "Ön interosseöz sinir", "Nervus interosseus antebrachii anterior", "Median sinirin derin dalı; FPL, FDP'nin radial yarısı ve pronator quadratus'u uyarır. Hasarında 'OK' işareti yapılamaz."),
    ("Palmar branch of median nerve", "Median sinirin palmar dalı", "Ramus palmaris nervi mediani", "Karpal tünelin üstünden geçen deri dalı; karpal tünel sendromunda tenar deri duyusu bu yüzden korunur."),
    ("Common palmar digital branches of median nerve", "Median sinirin ortak palmar dijital dalları", "Nervi digitales palmares communes nervi mediani", "Avuç içinde parmak aralarına uzanan dallar; ilk iki lumbrikali de uyarır."),
    ("Proper palmar digital branches of median nerve", "Median sinirin özel palmar dijital dalları", "Nervi digitales palmares proprii nervi mediani", "Başparmaktan yüzük parmağının yarısına kadar parmakların yanlarında seyreden duyu dalları."),
    ("(Communicating branch of median nerve with ulnar nerve)", "Median-ulnar birleşim dalı", "Ramus communicans cum nervo ulnari", "Avuç içinde median ve ulnar sinir arasındaki bağlantı (Riche-Cannieu benzeri anastomoz)."),
    ("Ulnar nerve", "Ulnar sinir (n. ulnaris)", "Nervus ulnaris", "Medial korddan çıkar, medial epikondilin arkasından ('komik kemik') geçer; el iç kaslarının çoğunu ve medial 1,5 parmağın duyusunu sağlar. Hasarında pençe el gelişir."),
    ("Muscular branches of ulnar nerve", "Ulnar sinirin kas dalları", "Rami musculares nervi ulnaris", "FCU ve FDP'nin ulnar yarısına giden dallar."),
    ("Palmar branch of ulnar nerve", "Ulnar sinirin palmar dalı", "Ramus palmaris nervi ulnaris", "Hipotenar deri dalı."),
    ("Dorsal branch of ulnar nerve", "Ulnar sinirin dorsal dalı", "Ramus dorsalis nervi ulnaris", "El sırtının medial kısmının duyusunu taşır; Guyon kanalından önce ayrıldığından kanal lezyonlarında korunur."),
    ("Dorsal digital branches of ulnar nerve", "Ulnar sinirin dorsal dijital dalları", "Nervi digitales dorsales nervi ulnaris", "Medial parmakların sırt yüzü duyusu."),
    ("Superficial branch of ulnar nerve", "Ulnar sinirin yüzeyel dalı", "Ramus superficialis nervi ulnaris", "Medial 1,5 parmağın avuç içi duyusunu ve palmaris brevis'i uyarır."),
